package com.primehr.learningdevelopment.domain;
import com.primehr.rsp.domain.RspAuditedEntity;import jakarta.persistence.*;import java.util.*;
@Entity @Table(name="ld_resource_person",uniqueConstraints=@UniqueConstraint(name="uk_ld_resource_person_code",columnNames={"agency_id","normalized_code"}))
public class LdResourcePerson extends RspAuditedEntity {
 public enum Source{EMPLOYEE,EXTERNAL} public enum Status{ACTIVE,INACTIVE}
 @Column(nullable=false,length=80)private String code;@Column(name="normalized_code",nullable=false,length=80)private String normalizedCode;@Enumerated(EnumType.STRING)@Column(name="person_source",nullable=false,length=20)private Source personSource;@Column(name="employee_no",length=100)private String employeeNo;@Column(name="display_name",nullable=false,length=250)private String displayName;@Column(name="provider_id",length=36)private String providerId;@Column(length=2000)private String expertise;@Column(length=2000)private String credentials;@Column(name="contact_details",length=1000)private String contactDetails;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private Status status;
 protected LdResourcePerson(){}public LdResourcePerson(String agency,String code,Source source,String employeeNo,String name,String provider,String expertise,String credentials,String contact){super(agency);status=Status.ACTIVE;apply(code,source,employeeNo,name,provider,expertise,credentials,contact);}
 public void update(String code,Source source,String employeeNo,String name,String provider,String expertise,String credentials,String contact){apply(code,source,employeeNo,name,provider,expertise,credentials,contact);}public void deactivate(){status=Status.INACTIVE;}public void activate(){status=Status.ACTIVE;}
 private void apply(String c,Source source,String employee,String name,String provider,String e,String q,String contact){code=requiredText(c,"code");normalizedCode=code.toUpperCase(Locale.ROOT);personSource=Objects.requireNonNull(source,"personSource");employeeNo=optionalText(employee);if(source==Source.EMPLOYEE&&employeeNo==null)throw new IllegalArgumentException("employeeNo is required for an employee resource person");if(source==Source.EXTERNAL&&employeeNo!=null)throw new IllegalArgumentException("employeeNo is not allowed for an external resource person");displayName=requiredText(name,"displayName");providerId=optionalText(provider);expertise=optionalText(e);credentials=optionalText(q);contactDetails=optionalText(contact);}
 public String getCode(){return code;}public Source getPersonSource(){return personSource;}public String getEmployeeNo(){return employeeNo;}public String getDisplayName(){return displayName;}public String getProviderId(){return providerId;}public String getExpertise(){return expertise;}public String getCredentials(){return credentials;}public String getContactDetails(){return contactDetails;}public Status getStatus(){return status;}
}
